const e=JSON.parse(`[{"key":"event-dashboard","routes":["/Home/Index","/","/Home/RenderIndex"],"keywords":["dashboard","home","home page","overview","stats","candidates count","pending approval","waiting for approval","enabled features","event countdown","registration trend","switch event","change event","my roles","coordinator dashboard"],"tasks":["Check who is waiting for approval","See which optional features are switched on","Switch to another event you manage"],"labels":["View All (Waiting for Approval)","X more waiting for approval","Enabled Features chip","Manage features","Candidates","Competitions","Participations","Judges","Teams","Age Groups","Event Stages","Results Published","Days to go / Registration Trend","Waiting for Approval"],"about":"Your event's home page: registration, competition and setup progress at a glance. The page you land on after logging in. It shows how registrations, competitions, scoring and event setup are progressing with counts, charts and quick links, so you can see what still needs attention without opening every setup page."},{"key":"competition-flow-guide","routes":["/Coordinator/CompetitionFlowGuide","/Coordinator/RenderCompetitionFlowGuide"],"keywords":["flow","guide","how to run a competition","workflow","steps","competition status","draw","scoring","results","walkthrough","life cycle","phases","what happens next"],"tasks":["Jump to a setup or results page","Find out why a competition is missing from a page"],"labels":[],"about":"A visual, step-by-step guide to how a competition runs from setup to results, with links to every page. A read-only walkthrough of the whole competition life cycle in 7 phases, from creating the event through registration, roles, the draw, scoring, and publishing results. Each step explains what happens and links straight to that page."},{"key":"manage-event","routes":["/SetUp/RenderManageEvent?tab=edit","/SetUp/RenderManageEvent","/SetUp/Events","/SetUp/EventsNew","/SetUp/RenderEvents"],"keywords":["event name","event dates","start date","end date","venue","edit event","organization name","event logo","manage event","update event details","competition type","event setup","change venue"],"tasks":["Change the event name, dates or venue"],"labels":["Edit","Submit","Event Name","Organization Name","Organization Short Name","Competition Type","Venue","Description","Start Date","End Date","Organization Logo","Event Logo","Background Image","Grade","Allow Awards","Allow SubCoOrdinators"],"about":"Edit your event's name, organization, dates, venue, logos and top-level switches. The Update Event Details tab of Manage Event. View and edit the event's name, organization, competition type, venue, dates, logos and switches like Grade, Awards and Sub-Coordinators. The other tabs on this page (Import Data, Duplicate Event, Warning Mails, Event Backup) are separate entries."},{"key":"import-data","routes":["/SetUp/RenderManageEvent?tab=import","/SetUp/ImportData"],"keywords":["import data","import event settings","import organizations","copy event","copy organizations","include candidates","coordinator email","bring in settings"],"tasks":["Import settings from another event","Import organizations from another event"],"labels":["Import Event Settings","Import Organizations","Event Name","Event Coordinator Email","Organization Name","Include candidates while importing organizations"],"about":"Copy another event's settings or organizations into the event you are in. The Import Data tab of Manage Event. Bring another event's settings, or its organizations (optionally with candidates), into the event you are currently in, by naming the source event, its coordinator's email and its organization name."},{"key":"duplicate-event","routes":["/SetUp/RenderManageEvent?tab=export","/SetUp/ExportData"],"keywords":["duplicate event","copy event","clone event","export data","assign to another user","export organizations","new event from existing","reuse event settings"],"tasks":["Duplicate this event"],"labels":["Duplicate Event","Assign duplicated event to a different user (optional)","Allow export organizations with duplicated event"],"about":"Make a full copy of this event, in your own account or assigned to someone else. The Duplicate Event tab of Manage Event. Creates a full copy of this event with all its settings, kept in your own account or assigned to another coordinator's email address, optionally including the event's organizations."},{"key":"warning-mails","routes":["/SetUp/RenderManageEvent?tab=warning","/SetUp/WarningMails"],"keywords":["warning mails","event review","setup warnings","scoring consistency","tied scores","missing configuration","send review email","check my event"],"tasks":["Send a warning review email"],"labels":["Send Warning Mails","Comprehensive Review","Event Setup Warnings","Participants & Management","Results & Scoring"],"about":"Send yourself an email review of possible setup, participant or results problems. The Warning Mails tab of Manage Event. Choose a category of automatic checks - Comprehensive Review, Event Setup Warnings, Participants & Management, or Results & Scoring - and send a detailed review email flagging missing configuration, inconsistent scores or tied ranks."},{"key":"event-backup","routes":["/SetUp/RenderManageEvent?tab=backup","/SetUp/EventBackup"],"keywords":["event backup","download event data","excel backup","coordinator backup","results backup","export event","save my data","backup my event"],"tasks":["Get a backup of your event data"],"labels":["Send Coordinator Backup","Send General Event Backup","Send Results Backup","Coordinator Backup","General Event Backup","Results Backup"],"about":"Email yourself a downloadable Excel backup of your event data. The Event Backup tab of Manage Event. Generates an Excel backup of your event data and emails you a secure download link. Choose Coordinator Backup, General Event Backup, or Results Backup depending on what you need saved."},{"key":"event-levels","routes":["/SetUp/ManageEventLevels","/SetUp/RenderManageEventLevels"],"keywords":["event levels","hierarchy","school house class","sub unit","zone","district","organization levels","parent level","level type","add level","org hierarchy"],"tasks":["Add a level to the hierarchy","Put a level under a different parent, e.g. Class under School instead of House","Remove a level you no longer need"],"labels":["Add Level","Show Inactive / Showing Inactive","Deactivate/Activate icon","Edit (pencil) icon","Delete (trash) icon","Order","Level Name","Parent Level","Type"],"about":"Define your event's organization hierarchy, for example School > House > Class. Set up the levels candidates belong to, such as School, House, Class or Zone, ordered from top to bottom. Sub-coordinators are assigned to a level, and award standings are calculated per level. Must be set up before candidates are added."},{"key":"ai-competitions-groups","routes":["/SetUp/RenderOpenAiCompetitionStructure"],"keywords":["ai","ai structure generator","auto generate competitions","upload rulebook","generate age groups","generate competitions","ai competitions and groups","split gender","smart setup"],"tasks":["Generate a competition structure from a rulebook"],"labels":["Upload Images or PDFs Related to the competition","AI Prompt","Get Results","Select all (header checkbox)","Row checkbox","Split Gender icon","Submit","Participant Type","Group Name","Competition Name","Language / Gender","Remarks","Maximum Score / Maximum Candidates / Fees","Maximum Minutes / Maximum Seconds","Minimum Minutes / Minimum Seconds"],"about":"Upload photos or PDFs of your event rules and let AI generate age groups and competitions. Upload images or PDFs describing your event, such as a rulebook, add a text prompt, and let AI suggest age groups, competition items, ranks, grades and the competitions assigned to each group. Review the generated list and install the rows you want."},{"key":"easy-start-review","routes":["/EasyStart/Review","/EasyStart/Install"],"keywords":["easy start","template","event template","installing event","setup progress","what was installed","ready made event","starter event","kalolsavam template","quick setup"],"tasks":["Watch your template install","Check and adjust what was installed"],"labels":["Yes, install it","Not now","Participant type buttons (e.g. Individual, Team)","Age groups / Competition items / Competitions / Users and roles (What's next cards)","Step list (Age groups, Competition items, Structure, Grade bands, Rank awards, Judging criteria)","Age groups","Competition items","Competitions by group"],"about":"Shows your event being set up from a template, then everything it installed. Two screens shown for an event created from an Easy Start template. Setting up your event shows live progress as age groups, competition items, structure, grades, ranks and judging criteria install. Once done, Your event is ready reviews everything installed and links to each setup page."},{"key":"age-groups","routes":["/SetUp/ManageGroups","/SetUp/RenderManageGroups","/Coordinator/RenderManageAgeGroups","/Coordinator/ManageAgeGroups","/SetUp/ManageGroupsOld","/AgewiseGroups/Manage"],"keywords":["age group","juniors","seniors","sub junior","age range","participant type","birth date","common group","age calculation date","group order"],"tasks":["Add an age group","Fix a wrong group order","Bulk edit several groups","Delete a group that is in use"],"labels":["Add New Group","Show Inactive","Fix Order","Edit (pencil icon)","Delete (trash icon)","Activate/Deactivate (circle icon)","Where this group is used (link icon)","Edit N selected","Delete N selected","Table / Cards","Group Name","Participant Type","Status","Age From / Age To","Age Calculation Date","Is Common Group","No Age-Based ID Prefix","Allow Overlapping Age Range","Unit level (e.g. Classes)"],"about":"Create and manage age-based groups like Sub Junior, Junior and Senior that participants are placed into. Set up the age groups participants are placed into, such as Sub Junior, Junior and Senior. Each group has an age range, a participant type (Individual, Team or Any) and can be linked to school units. Competitions and results are organized around these groups."},{"key":"competition-names","routes":["/SetUp/ManageCompetitionItems","/SetUp/RenderManageCompetitionItems","/Coordinator/RenderManageCompetitionItems","/Coordinator/ManageCompetitionItems","/SetUp/ManageCompetitionItemsOld"],"keywords":["competition item","program","event item","kalolsavam item","category","scoring method","marks","rating","time strategy","add program"],"tasks":["Add a competition item","Reorder competition items"],"labels":["Add New Competition","Bulk Edit","Bulk Delete","Fix Order","Edit (pencil icon)","Delete (trash icon)","Enable/Disable (power icon)","Drag (handle icon)","Category filter","Competition Title","Competition Type","Scoring Method","Display Order","Time Strategy","Image URL"],"about":"Create and manage the list of competitions/programs (e.g. Solo Singing) and how each is scored. Set up every competition or program run at the event, such as Solo Singing or Elocution. Each item has a category, a scoring method and a display order. This list is used everywhere else: assigning to groups, scheduling, judging and publishing results."},{"key":"assign-competitions","routes":["/CompetitionStructure/RenderTab","/CompetitionStructure/Tab","/CompetitionStructure/Tab?tab=list","/CompetitionStructure/Tab?tab=matrix"],"keywords":["assign competition","structure","list view","matrix view","language","gender","max score","time limit","fees","competition status"],"tasks":["Assign a competition to a group","Assign many combinations at once","Use Matrix View"],"labels":["New","Bulk Create","Fix Order","Edit N selected","Delete N selected","Edit (pencil icon)","Delete (trash icon)","Click an empty matrix cell","... (matrix cell control)","Participant Type / Group / Competition Item","Language","Gender","Status","Maximum Score","Max Time / Warning Time (m","Fees / Remarks"],"about":"Assign competitions to age groups and set each combination's language, gender, score, time and status. Link each competition to the age groups running it, and set details per combination: language, gender, maximum score, time limit, warning time, fee and status. Use List View to manage rows one at a time, or Matrix View to assign a whole group-by-competition grid at once."},{"key":"structure-status","routes":["/CompetitionStructure/Status","/CompetitionStructure/RenderStatus"],"keywords":["structure status","competition status","not started","on progress","finished","published","cancelled","progress tracker","setup status"],"tasks":["Update a competition's status"],"labels":["Status dropdown (per row)","Participant Type / Group / Competition Item","Language / Gender","Status"],"about":"See and update the progress status of every assigned competition, grouped by status. Shows every assigned competition grouped by its progress status — Not Started, Yet To Begin, On Progress, On Review, Finished, Published, Cancelled — so you can track and update where each competition stands."},{"key":"scoring-setup","routes":["/SetUp/RenderScoreSettings","/SetUp/ScoreSettings","/SetUp/ScoreSettings?tab=rank","/SetUp/ScoreSettings?tab=grade","/SetUp/ScoreSettings?tab=criteria","/SetUp/ScoreSettings?tab=points"],"keywords":["rank","grade","bonus points","judges rating criteria","judging criteria","participation points","marks","first second third","scoring setup","grade bands"],"tasks":["Add rank bonus points","Add judging criteria","Set participation points"],"labels":["New Rank / New Grade / New Criteria / New Participation Points","Bulk Add with Values","Bulk Disable","Import from another event (Judges Rating Criteria tab)","Active / Inactive filter","Edit / Delete (icons)","Edit N selected / Delete N selected","Install (Rank/Grade tabs)","Rank Title / Bonus Points","Grade Name / Value (%)","Criteria Name","Criteria Score","Participation Points","Participant Type / Group / Competition"],"about":"Set rank bonus points, grade bands, judges' rating criteria and participation points for competitions. Configure how competitions are scored across four tabs: Rank (bonus points per finishing position), Grade (grade bands), Judges Rating Criteria (what judges score against) and Participation Points (flat points for taking part). Each entry can be scoped to a participant type, group and/or competition."},{"key":"import-criteria","routes":["/SetUp/RenderImportCriteria","/SetUp/ImportCriteria"],"keywords":["import criteria","copy judging criteria","another event","judges rating criteria","reuse criteria","duplicate criteria","criteria preview","copy scoring"],"tasks":["Import criteria from another event"],"labels":["Source event","Refresh","Refresh preview","Select all","Summary chips (Ready, Exists, etc.)","Import N criteria","Open Scoring Setup","Criteria","Age group","Participant type","Score","Status"],"about":"Copy judges' rating criteria from one of your other events into this event. Copy judging criteria already set up on another event you created or coordinate into this one, instead of re-typing them. Criteria are matched to this event by competition name and age group name; only matching rows are importable, and existing criteria are never changed."},{"key":"id-card-config","routes":["/SetUp/RenderIdPrefix","/SetUp/IdPrefix","/SetUp/IdPrefix?tab=unique","/SetUp/IdPrefix?tab=chest","/SetUp/IdPrefix?tab=draw"],"keywords":["chest number","bib","id prefix","unique id","draw id","chest no prefix","identity card number","id card config","chest card","prefix length","easy install"],"tasks":["Set a chest number prefix","Quickly set up chest numbers for every group","Bulk edit several prefixes"],"labels":["Add Prefix","Bulk Edit","Bulk Delete","Select all","Install Selected (Easy Install, Chest Card tab only)","Edit (pencil icon)","Delete (trash icon)","Participant Type / Gender / Group / Competition Item","Identity Card Number Start With","Identity Card Number Length","Sample Output"],"about":"Set the prefix and number format used for chest numbers, unique IDs and draw IDs. Configure the text prefix and number length used to generate participant identity numbers: the Chest Card number on ID cards, a separate internal Unique ID, and the numbers used for the draw (lot) order. Each rule can be scoped by participant type, gender, group and competition."},{"key":"advanced-config","routes":["/SetUp/RenderEventAdvancedSettings","/SetUp/EventAdvancedSettings"],"keywords":["advanced settings","advanced config","turn off registration","close registration","disable registration","enable registration","starting soon","skip approval","auto approve","freeze event","lock event","disable groups","fees currency","hide fees"],"tasks":["Turn off public registration","Temporarily close registration with a starting-soon notice","Lock the event so nobody can make changes"],"labels":["Save All Changes","Public Registration Form","Public Event Pages","Disable Individual/Team Registration","Individual/Team Registration Starting Soon","Skip Approval Step","Allow/Require Phone, Email, Gender, Photo","Disable Groups / Group Size limits","Freeze All Edits / Freeze SubCoordinator Access","Fees Currency / Hide Fees Publicly"],"about":"Turn dozens of event-wide switches on or off: registration, fees, groups, printouts and more. A searchable grid of on/off switches controlling how the event behaves, from opening or closing public registration to what shows on printouts. Change what you need, then save once."},{"key":"max-participation","routes":["/SetUp/RenderMaxParticipation"],"keywords":["max participation","participation limit","competitions per candidate","limit competitions","category limit","cap registrations","how many competitions can a candidate join","maximum entries","participation rule"],"tasks":["Add a participation limit for a category","Change an existing limit","Remove a limit"],"labels":["Add Rule","Update Rule","Cancel","Edit","Delete","Save All Changes","Competition Category","Maximum Participation"],"about":"Set a custom maximum number of competitions a candidate can enter, for one competition category. Override the event's default participation limit for a specific competition category, for example allowing more or fewer entries than usual in one category. Add one rule per category and save."},{"key":"eligible-registrations","routes":["/SetUp/RenderEligibleRegistrationNumbers"],"keywords":["eligible registration","registration whitelist","registration number","allowed to register","pre-approved list","reg number","csv upload","who can register","issued to","approved list"],"tasks":["Add registration numbers from a CSV file","Add one registration number by hand","Remove a registration number"],"labels":["Upload CSV File","Download Template","Add to List","Cancel","Add","Update","Edit","Delete","Save All Changes","Registration Number","Issued To","Contact Number"],"about":"Maintain a whitelist of registration numbers allowed to register for the event. Add the registration numbers you have already issued, with the person's name and phone number, so only people on this list can register. Add numbers one at a time or upload a CSV file."},{"key":"public-registration","routes":["/SetUp/ManagePublicRegistrationForm"],"keywords":["public registration form","registration form","turn off payment","disable payment","remove payment","online registration","sign up form","registration link","qr code","team registration","individual registration","upi"],"tasks":["Turn off payment on the registration form","Turn off public registration completely","Add or remove a field on a step"],"labels":["Reset to Defaults","Live Preview","Live Event View","Remove All","Save","Copy / Paste","Show Logo / Logo Width (QR Code tab)","Use Live URL (QR Code tab)"],"about":"Build the public online registration form: fields, payment step, emails, public page text and QR code. Design what candidates and teams fill in when they register online, step by step, plus the confirmation emails and public page text. Six tabs group these steps."},{"key":"theme-settings","routes":["/Settings/ThemeSettings"],"keywords":["theme","dark mode","light mode","classic theme","colour theme","appearance","change theme","theme settings"],"tasks":["Change your theme"],"labels":["(theme card)"],"about":"Pick the app's colour theme — light, dark or classic — for your own screen. Choose which colour theme the app displays. Every theme applies the moment you click it — there is no separate Save."},{"key":"features","routes":["/Settings/Features","/Settings/RenderFeatures"],"keywords":["features","unlock page","hide page","locked page","menu features","feature list","unlock all","getting started","more features"],"tasks":["Unlock an optional feature","Unlock everything at once","Hide a feature you unlocked"],"labels":["Unlock all (N)","Open","Unlock","Hide from menu","Always available / Unlocked / Locked","Unlocks automatically"],"about":"See every page in the app, whether it's unlocked yet, and unlock or hide optional ones. The menu reveals pages step by step as you set up your event. This page lists every page, grouped as Getting Started, Unlocked by Your Setup Flow and More Features, and lets you open, unlock, hide, or unlock everything at once."},{"key":"bulk-participants","routes":["/Coordinator/ManageBulkParticipants2","/Coordinator/RenderManageBulkParticipants"],"keywords":["add participant","bulk participants","assign competition","assign student to competition","participant grid","edit participant","delete participant","photo upload","identity number","registration id","reset identity number","age group filter"],"tasks":["Add a participant","Assign an existing participant to more competitions"],"labels":["Add Participant","Photo icon on a row","Edit (pencil icon)","Edit competitions (tag icon)","Manage team (icon with a number)","Reset identity number","Delete (trash icon)","Competition checkbox columns","Filters","Clear filters","Photo, ID, Name/Team Name, Gender, DOB, Email, Mobile, Registration Id","Search by name; Identity Number / Registration Id search boxes."],"about":"Add participants and tick them into competitions in one dense grid, organized by age group. Manage everyone entered for one age group and one participant type (Individual or Team): add new participants, edit their details inline, upload photos, and tick or untick which competitions each one is in."},{"key":"excel-import","routes":["/Coordinator/RenderExcelImport"],"keywords":["excel import","csv import","bulk import","paste participants","chest number","identity number","duplicate participant","add class and division","assign students to competitions","data can't save"],"tasks":["Import participants from a spreadsheet","Assign competitions and class/division while importing"],"labels":["Upload CSV/Excel File","Import to List","Clear All","Import / Import Comps (per row)","Confirm All","Skip","Add Groups","UserName, IdentityNumber (chest number), RegistrationId, GroupName (only if no single group filter is chosen).","UserDob (with / or -), UserGender (Male/Female).","Level columns (e.g. SchoolName, ClassName)","UserPhone / UserMobile / UserEmail / UserProfilePicture.","Competition columns"],"about":"Paste or upload a spreadsheet of participants and import them, matched to age groups and competitions. Add or update many participants at once from a CSV or Excel file instead of typing them one by one. Each row is checked against your event's real groups and competitions, problems are flagged, and you import row by row or all at once."},{"key":"ai-participant-import","routes":["/Coordinator/RenderAiParticipantImport"],"keywords":["ai import","photo import","image import","scan participant list","handwriting import","upload pdf","bulk edit","chest number","membership","duplicate participant","get results"],"tasks":["Import a participant list from a photo","Update several rows at once"],"labels":["Upload an image of your participant list","AI Prompt","Get Results","Bulk Edit (N)","Import Selected Participants","Delete row (trash icon)","Existing-name match","Type","DOB, Gender, Phone, Email (individuals only).","Reg. Id","Competitions","Membership"],"about":"Upload photos or a PDF of a participant list and let AI read out names, groups and competitions for you to check and import. Use this page when your participant list is a photo, scan or PDF instead of a spreadsheet — for example a handwritten sheet. AI reads it into an editable table, tries to match each row to an existing participant to avoid duplicates, and you fix anything wrong before importing."},{"key":"candidates","routes":["/Coordinator/ManageCandidatesNew","/Coordinator/RenderManageCandidates","/Coordinator/ManageCandidates"],"keywords":["candidates","add candidate","edit candidate","delete candidate","fix age group","wrong age group","excel import candidates","roster","identity number","registration id","age group mismatch"],"tasks":["Add a candidate","Fix a candidate's age group","Import many candidates from Excel"],"labels":["Add Candidate","Import Excel","Fix Age Groups","Edit (pencil icon)","Delete (trash icon)","Delete N selected","Search by Identity No. / Search by Registration Id / Search by Name.","Candidate","Gender, Identity No. (Coordinator only), Reg. ID, Group, DOB.","Per-level columns (e.g. House)","Phone, Mobile, Email, Created By, Date."],"about":"List, add, edit, delete and bulk-fix the age group of candidates — without assigning competitions here. Manage the roster of individual candidates: register new ones by hand or by pasting Excel rows, correct mistakes, remove people, and move mis-grouped candidates into their correct age group. Assign competitions from Bulk Participants instead."},{"key":"candidate-profile","routes":["/Coordinator/CandidateProfile","/Coordinator/RenderCandidateProfile"],"keywords":["candidate profile","candidate details","judge scores","results history","activity log","guardian info","team participation","view candidate"],"tasks":[],"labels":[],"about":"A read-only profile of one candidate: their details, competitions, teams, judge scores, results and activity. Open this from a candidate's Profile link to see everything recorded about them in one place across tabs. Nothing on this page can be edited."},{"key":"teams","routes":["/Coordinator/ManageTeamsNew","/Coordinator/RenderManageTeams","/Coordinator/ManageTeams"],"keywords":["team","add team","team name","team directory","team strength","delete team","team identity number","manage teams"],"tasks":["Add a team","Add members or competitions to a team"],"labels":["Add Team","Edit","Delete","Delete Selected (N)","Team name (click)","Search","Team Name, Identity Number (Coordinator only), Strength (member count).","Per-level unit columns (e.g. House), Created By, Created Date."],"about":"Create and manage team profiles — name, identity number and unit — without assigning members or competitions here. Keep the directory of teams used for team-type competitions. Add a team's name and unit, edit or delete teams, and open a team to assign its members and competitions elsewhere."},{"key":"assign-teams","routes":["/CompetitionParticipantsTeamMembers/ManageNew","/CompetitionParticipantsTeamMembers/RenderManage","/CompetitionParticipantsTeamMembers/Manage"],"keywords":["assign team","team member","team leader","team designation","add member to team","team roster","captain","assign candidate to team"],"tasks":["Assign a candidate to a team"],"labels":["Add","Edit (pencil icon)","Save / Cancel","Delete (trash icon)","Remove Selected (N)","Clear filter","Search","Designation (Leader/Member), Candidate, Team, Order.","Event (SuperAdmin/User only), Modified Date."],"about":"Assign candidates to teams with a role (Leader or Member). Build up each team's roster by linking existing candidates to a team and giving them a designation. Open from a team's name on Teams to see just that team's members, or manage everyone here."},{"key":"review-candidates","routes":["/Coordinator/RenderCandidatesDetailedList"],"keywords":["review candidates","approve registration","approval status","waiting for approval","public registration review","reject candidate","pending candidates","in progress"],"tasks":[],"labels":["Search","View","Profile","Delete","Remove (on a competition chip)","Zip / Excel export icons","Call / WhatsApp icons","Status","Name, Registration Id, Identity Number (Coordinator only), Group, unit levels, Competitions, Total (fees), Members (Team tab)."],"about":"Review public self-registrations, see their approval status, and approve, view, or remove their competitions. Check candidates and teams who registered through the public registration form: see how far they got, their competitions and fees, then approve or review them, open their details, or delete them. Switch between Individual and Team."},{"key":"send-reminders","routes":["/Coordinator/SendReminders","/Coordinator/RenderSendReminders"],"keywords":["send reminders","reminder email","invite past participants","notify participants","opted out","re-invite","past events","email participants"],"tasks":["Send reminders"],"labels":["Select-all checkbox","Send Reminders","Status filter","Search","Total Eligible, Not Sent, Already Sent, Opted Out","Per person"],"about":"Email people who took part in your other events to invite them to this new event. Find people who took part in your previous events and send them a reminder email about this one. Filter by whether a reminder was already sent, search by name, email or mobile, then select and send."},{"key":"sub-units","routes":["/Coordinator/SubUnitsNew","/Coordinator/RenderSubUnits","/Coordinator/SubUnits"],"keywords":["houses","classes","divisions","sub units","local management","organizational units","add house","add class","add division","parent organization","unit management","zone","district","school"],"tasks":["Add a unit (e.g. a class or division)","Rename or renumber a unit"],"labels":["Add {Level Name}","Edit (pencil icon)","Delete (trash icon)","Shuffle {Level Names} Order","Ascending Order Reset","Remove Zero Candidates","Search","Name, Short Name, Competition Level, Parent Organization, Order.","Sub Coordinators, Candidates, Teams, Child Organizations (counts), Created By, Created Date."],"about":"Create and manage the event's organizational units below the top level, such as Houses, Classes or Divisions. Set up the lower-level groups candidates and teams belong to — for example House then Class then Division. Add a unit for each level, rename or renumber existing ones, and run bulk clean-up tools."},{"key":"event-submission","routes":["/Coordinator/RenderEventSubmission"],"keywords":["event submission","copy participants","import from another event","cross event import","bring results","rank filter","first second third place","coordinator events","duplicate event data"],"tasks":["Copy participants from another event"],"labels":["Select Source Event","Rank checkboxes","Prepare for Import","Import to List","Clear All","Import (per row)","Confirm All","Skip","Select Source Event","Import Participants by Rank (Optional)"],"about":"Copy participants (and optionally only certain result ranks) from another event you coordinate into this one. Use this page when you coordinate more than one event and want to bring participants into this event instead of re-entering them. Pick the source event, load its data, then review and import it the same way as Excel Import."},{"key":"id-cards","routes":["/Coordinator/CandidatesCardsNew","/Coordinator/CandidatesCardsNew/:profileName","/Coordinator/RenderCandidatesCards","/Coordinator/CandidatesCards"],"keywords":["id card","identity card","chest number","bib number","badge","id badge","lanyard","print id cards","candidate card","participant card","card design","design profile","card template","background image","photo id card"],"tasks":["Print ID cards for a group","Choose a look and background","Create a separate design profile","Restyle one part of the card"],"labels":["New profile","Options","Load Candidates","Print","Download","Upload background","Delete (trash icon)","Delete all profiles","Share (WhatsApp icon)","Group","Competition","Participant Type","Card number","Filter by ID numbers","Additional cards","Cards per row / Rows per page","Card layout","Heading / Logo 1 URL","Hide profile photos / Hide photo on team cards / Hide team members"],"about":"Design candidate ID cards - pick a look and background, then print or download a full sheet. Design candidate ID cards and print or download them. Pick a background and look, filter which candidates to include, then print or save a full sheet of cards for one group."},{"key":"staff-id-cards","routes":["/Coordinator/StaffCardsNew","/Coordinator/StaffCardsNew/:profileName"],"keywords":["staff id card","judge card","executive card","judge badge","staff badge","lanyard","committee card","office bearer card","president secretary card","print staff cards","staff card design","staff card profile","role card","judges executives"],"tasks":["Print cards for judges or executives","Add judges or executives if none are found","Choose a look and background","Create a separate profile for each role"],"labels":["New profile","Options","Load Profiles","Print","Download","Upload background","Delete (trash icon)","Delete all profiles","Share (WhatsApp icon)","Add Judges / Add Executives","Role","Cards per row / Rows per page","Card layout","Heading / Logo 1 URL","Hide profile photos","Position"],"about":"Design and print ID badges for Judges and Executives - pick a role, a look, then print or download. Design and print ID badges for Judges and Executives. Pick which role to load, choose a background and look, then print or download a full sheet of their cards."},{"key":"print-by-competitions","routes":["/Coordinator/PrintCompetitionCandidates","/Coordinator/RenderPrintCompetitionCandidates","/Coordinator/RenderLocalWiseParticipants","/Coordinator/LocalWiseParticipantsNew","/Coordinator/LocalWiseParticipants"],"keywords":["call sheet","chest number","draw number","competition candidates","local wise participants","print participants","by competition","shuffle order","excel export","pdf","candidate list","competition roster"],"tasks":["Print candidate lists for competitions","Shuffle the call sheet order","Export the list to Excel"],"labels":["Options","Generate","Print","Download","Export to Excel","Excel (Line by Line)","Shuffle Call Sheet Order","Reset Call Sheet Order","Generate Competition Draw Numbers","Competition Status","Group","Competition Item","Competition Order Number","Competition","Order By","Chest No.","Id No.","Name","Photo","Additional Data"],"about":"Print or export the candidate list for every competition, grouped under each competition heading. Shows every candidate registered for each competition as a printable sheet, grouped by competition. Use it to prepare call sheets before an event, check who is registered where, or export the list to Excel."},{"key":"print-by-participant","routes":["/Coordinator/ParticipantsWiseCompetitionsNew","/Coordinator/RenderParticipantsWiseCompetitions","/Coordinator/ParticipantsWiseCompetitions"],"keywords":["participant competitions","by participant","candidate schedule","competition list per candidate","header line","registration id","draw number","excel export","pdf","print participants"],"tasks":["Print each participant's competition list","Export participant competitions to Excel"],"labels":["Options","Generate","Print","Download","Export to Excel","Excel (Line by Line)","Age Group","Competition Item","Allow Identity Number","Allow Count Field","Allow Gender / Allow Membership Id / Allow Phone / Allow Mobile / Allow Email / Allow Date of Birth","Competition Name","Index"],"about":"Print or export each participant's own list of competitions, one heading per candidate with their competitions underneath. Shows a printable sheet for every candidate or team, listing all the competitions they are registered for underneath their name. Use it to give each participant their own competition list, or check registrations per person."},{"key":"print-by-unit","routes":["/Coordinator/RenderMemberShipWiseParticipants","/Coordinator/MemberShipWiseParticipantsNew","/Coordinator/MemberShipWiseParticipants"],"keywords":["by unit","division","house wise","church wise","membership wise","unit wise participants","total fees","fees per unit","print participants","team fees"],"tasks":["Print candidates grouped by unit","See total fees and candidates per unit"],"labels":["Options","Generate","Print","Download","Export to Excel","Excel (Line by Line)","<Level Name>","Age Group","Individual / Team","Mixed Teams","Per Candidate Fees for Team Candidates","Name / Id No. / Registration ID","Chest No.","Competitions","Fees","Guardian Name/Email/Mobile/Phone"],"about":"Print or export the candidate list grouped by organization unit (e.g. Division, House, Church), with per-unit totals. Shows every candidate grouped under their organization unit - the event's own lowest level, such as Division or House - with columns like competitions and fees. Use it to print rosters per unit or check fees per unit."},{"key":"score-sheets","routes":["/Coordinator/PrintScoreCardNew","/Coordinator/RenderPrintScoreCard","/Coordinator/PrintScoreCard"],"keywords":["score sheet","judge sheet","mark sheet","judges score card","blank score card","print judges","scoring criteria","competition title","competition name format","competition full name","print score card"],"tasks":["Print score sheets for judges","Change how the competition name prints on the sheet"],"labels":["Options","Generate","Print","Download","Score Status","Judge","Competition","Candidate Order By","Criteria Layout","Color Theme","Allow Judge Name","Id No. Font Size","Criteria Width","Tables Per Row"],"about":"Print blank score sheets for judges - one sheet per judge per competition, with criteria and space to write scores. Generates a printable score sheet for each judge/competition pair, listing participants and scoring criteria with blank spaces to write marks. Use it before judging starts to hand out sheets to each judge."},{"key":"reports","routes":["/Coordinator/Reports","/Coordinator/RenderReports"],"keywords":["report builder","custom report","export excel","export csv","export pdf","group by","saved views","print data","participants report","scores report"],"tasks":["Build and print a report","Save your own report as a reusable view"],"labels":["Generate","Export to PDF","Export to Excel","Excel Line By Line","CSV","Refresh","Columns","+ Add sort field","Report","Columns","Group By","Sort Order","Page Size","Orientation"],"about":"Build a custom printable or exportable report - pick a ready-made report type or build your own with columns, filters and grouping. A flexible report builder for printing or exporting participant, competition and score data. Choose a built-in report type, or set your own columns, filters, grouping and paper style, then export to PDF, Excel or CSV."},{"key":"invite-subcoordinators","routes":["/UsersAndRoles?operation=SubCoordinator","/Setup/RenderUserRoles/SubCoordinator/:eventCategory/:eventId"],"keywords":["invite subcoordinator","add subcoordinator","sub coordinator","school coordinator","resend invite","remove subcoordinator","access mode","editable readable","assign unit","manage subcoordinators"],"tasks":["Invite a new SubCoordinator","Resend login details","Remove a SubCoordinator"],"labels":["Add New User","Import Users","Edit","Share login details","Remove","Missing (wrench icon)","Full Name","Email Address","Profile Picture","Invite Link Version","<Level> Name","Access Mode","Accessible Sections","Organization (column)"],"about":"Invite and manage SubCoordinators for one level of the event, for example School or District. Use this page to invite SubCoordinators for one level of your event, edit their unit and access mode, resend login details, or remove them. A separate menu link and page exists for each level the event uses."},{"key":"invite-judges","routes":["/UsersAndRoles?operation=Judge","/UsersAndRoles","/RenderUsersAndRoles","/Setup/RenderUserRoles","/Setup/RenderUserRoles/Judge/:eventCategory/:eventId"],"keywords":["invite judge","add judge","judges","resend invite","remove judge","judge login","share login details","judge password","users and roles"],"tasks":["Invite a new Judge","Resend login details","Remove a Judge"],"labels":["Add New User","Import Users","Add Yourself as Judge","Edit","Share login details","Remove","Assign Competitions","Not now","Full Name","Email Address","Profile Picture","Invite Link Version","Organization (column)"],"about":"Invite and manage Judges for this event, and jump to assigning them competitions. Use this page to invite Judges, edit their details, resend their login details, or remove them. After adding a new Judge you can go straight to assigning competitions to them."},{"key":"executives","routes":["/UsersAndRoles?operation=Executive","/Setup/RenderUserRoles/Executive/:eventCategory/:eventId"],"keywords":["invite executive","add executive","executive position","president","secretary","office bearer","remove executive","executives list","committee member"],"tasks":["Add a new Executive","Remove an Executive"],"labels":["Add New User","Import Users","Add Yourself as Executive","Edit","Remove","Full Name","Position","Email Address","Profile Picture","Invite Link Version","Organization (column)"],"about":"Invite and manage Executives, event staff with a position title printed on their staff ID card. Use this page to add Executives such as a President or Secretary, set the position title printed on their staff ID card, or remove them. An email address is optional for Executives, since they may not need to log in."},{"key":"content-viewer","routes":["/UsersAndRoles?operation=ContentAdmin","/Setup/RenderUserRoles/ContentAdmin/:eventCategory/:eventId"],"keywords":["invite content viewer","content admin","add content viewer","content viewer role","remove content viewer","view only user","read only user"],"tasks":["Invite a new Content Viewer","Resend login details","Remove a Content Viewer"],"labels":["Add New User","Import Users","Add Yourself as ContentAdmin","Edit","Share login details","Remove","Full Name","Email Address","Profile Picture","Invite Link Version","Organization (column)"],"about":"Invite and manage Content Viewers for this event. Use this page to invite Content Viewers, edit their details, resend their login details, or remove them."},{"key":"draw-masters","routes":["/UsersAndRoles?operation=DrawMaster","/Setup/RenderUserRoles/DrawMaster/:eventCategory/:eventId"],"keywords":["invite draw master","add draw master","draw masters","draw master login","remove draw master","draw management","score master"],"tasks":["Invite a new Draw Master","Resend login details","Remove a Draw Master"],"labels":["Add New User","Import Users","Add Yourself as DrawMaster","Edit","Share login details","Remove","Full Name","Email Address","Profile Picture","Invite Link Version","Organization (column)"],"about":"Invite and manage Draw Masters, who help run the competition draw. Use this page to invite Draw Masters, edit their details, resend their login details, or remove them. Draw Masters are grouped under draw management access."},{"key":"projector-access","routes":["/UsersAndRoles?operation=Projector","/Setup/RenderUserRoles/Projector/:eventCategory/:eventId"],"keywords":["invite projector user","projector access","projector login","screen operator","add projector","remove projector user"],"tasks":["Invite a new Projector user","Resend login details","Remove a Projector user"],"labels":["Add New User","Import Users","Add Yourself as Projector","Edit","Share login details","Remove","Full Name","Email Address","Profile Picture","Invite Link Version","Organization (column)"],"about":"Invite and manage people with Projector Access (a login for the screen or projector operator). Use this page to invite people who need Projector Access, edit their details, resend their login details, or remove them. The role is grouped under time management access."},{"key":"stage-managers","routes":["/UsersAndRoles?operation=StageManager","/Setup/RenderUserRoles/StageManager/:eventCategory/:eventId"],"keywords":["invite stage manager","stage managers","add stage manager","assign stage to manager","stage manager login","remove stage manager"],"tasks":["Invite a new Stage Manager","Change the stage of a Stage Manager","Remove a Stage Manager"],"labels":["Add New User","Quick add row (top of the list)","Import Users","Edit","Share login details","Send invitation email","Remove","Full Name","Stage","Email Address","Profile Picture","Invite Link Version"],"about":"Invite and manage Stage Managers, each looking after one stage of the event. Use this page to invite Stage Managers, choose the one stage each of them looks after, edit their details, resend their login details, or remove them. A Stage Manager sees only that stage, on the My Stage page. The role is grouped under time management access."},{"key":"manage-coordinators","routes":["/Coordinator/SubCordinators","/Coordinator/RenderSubCordinators","/Coordinator/ContentAdmin","/Coordinator/RenderContentAdmin","/Coordinator/DrawMaster","/Coordinator/RenderDrawMaster","/Coordinator/projector","/Coordinator/RenderProjector","/Coordinator/Judges","/Coordinator/RenderJudges"],"keywords":["old users page","manage coordinators","old manage users","legacy role page"],"tasks":["Add a person to this role","Resend login details","Remove a person"],"labels":["Add","WhatsApp","Remove","Name","Email","User Account","# / Name / Email (columns)","Level columns","Search box"],"about":"Older page for adding and removing SubCoordinators, Draw Masters, Content Viewers, Projector users or Judges, one role per link. This is an earlier version of the Users & Roles screen, reused for five roles; which one it manages depends on the link you opened. It only supports adding and removing people, not editing them."},{"key":"assign-judges","routes":["/JudgesAllotment/RenderManage","/JudgesAllotment/ManageNew","/JudgesAllotment/Manage"],"keywords":["assign judges","judges allotment","allot judges","by judge","by competition","invite judges","unassign judge","remove judge","bulk assign judges","score status","allowed to fill","judge assignment","judges to competition"],"tasks":["Assign a judge to a competition","Bulk-assign one judge to many competitions","Invite a new judge"],"labels":["Invite Judges","Assign/unassign tick","Status badge (Fill/Publish/Allowed to fill)","Select / Cancel Selection","Select all","Assign (N)","Untick / unassign (N)","Update score status (N)","Clear","Competitions assigned","Judges assigned","Score status"],"about":"Assign judges to competitions, and track each judge's score-entry status, by judge or by competition. Allot judges to competitions for the event, toggle each allotment's status (Allowed to fill, Filled, Published), and bulk-assign or bulk-update many at once. Judges must be assigned here before they can score on Judge Scoring."},{"key":"judge-scoring","routes":["/Coordinator/RenderScoreCardV2","/Coordinator/ScoreCardV2"],"keywords":["judge scoring","score card","scorecard","enter scores","judge panel","scoring panel","mark as finished","mark absent","criteria score","total score","hide score","reveal score","locked competitions","view only scores","score participant"],"tasks":["Score a candidate","Finish a judge's scoring","Review locked scores"],"labels":["Save Score / Update Score","Delete","Mark as Absent","Mark As Finished","Hide Score / Reveal Score","Allow Score Above Maximum","Criteria","Total","Notes","Candidate list"],"about":"Enter or view participant scores for a competition, as a judge or on a judge's behalf. This is where scores are actually entered. Pick a competition and (coordinators) a judge, then score each participant by criteria or a single total, mark absentees, and finish a judge's scoring when done."},{"key":"view-scores","routes":["/JudgesScoreCard/ManageNew","/JudgesScoreCard/RenderManage","/JudgesScoreCard/Manage"],"keywords":["view scores","judge scores","score report","scorecard","delete score","judging results","candidate scores","team scores","bonus points","calculated score","grade","phase scores"],"tasks":["Find a judge's scores","Remove a wrong score","Remove several scores"],"labels":["Search","Reset","Columns","Delete","Delete Selected (N)","Competition","Judge","Candidate ID","Team ID","Phase","Score / Grade / Bonus / Calculated"],"about":"Review every score a judge has recorded, with timing, grade and points, and delete wrong entries. Search and check the scores judges submitted, per competition, judge, candidate or team. Scores can be deleted here (individually or in bulk) if a judge made a mistake, but not edited."},{"key":"criteria-breakdown","routes":["/JudgesDetailedScoreCard/ManageNew","/JudgesDetailedScoreCard/RenderManage","/JudgesDetailedScoreCard/Manage"],"keywords":["criteria breakdown","judging criteria","per criteria score","detailed score card","criterion scores","rating criteria","how score was calculated","criteria order"],"tasks":["Check one score card's criteria","Find criteria scored with a specific value"],"labels":["Search","Reset","Score Card ID","Score","Criteria","Order","Modified Date"],"about":"See the individual criterion-by-criterion scores behind each judge's total score card. A read-only table of every judging criterion a judge scored inside a score card, so a coordinator can see exactly how a total score was built up."},{"key":"score-history","routes":["/ScoreLog/ViewNew","/ScoreLog/RenderView","/ScoreLog/View"],"keywords":["score log","score history","judging log","who scored","score audit","score trail","judge activity log","candidate score history","team score history"],"tasks":["See the score log","Find one candidate's or team's history"],"labels":["Filter","« Prev / Next »","Log","Judge","Candidate Identity Number","Team Identity Number","Score"],"about":"Search a log of recorded scores by judge, candidate, team or competition. Look up the score log for the event — what was scored, by which judge, for which candidate/team and competition. Read-only, filtered by text search, one page of results at a time."},{"key":"schedule-table","routes":["/CompetitionSchedule/RenderManage","/CompetitionSchedule/ManageNew","/CompetitionSchedule/Manage"],"keywords":["schedule table","timetable","time slot","assign stage","schedule a competition","bulk create schedule","duplicate schedule","reorder schedule","print schedule","run sheet","scheduled start time","scheduled end time","stage assignment"],"tasks":["Schedule a competition","Bulk-create schedules","Reorder, edit or delete a row","Print the schedule"],"labels":["Add Schedule","Bulk Create","Edit","Delete","Duplicate Selected (N)","Delete Selected (N)","Move up / Move down","Change stage to... / Change order to","Search by competition or stage...","Print Schedule","Order","Competition","Stage","Scheduled Start/End","Reported Start/End","Display Order"],"about":"Manually assign each competition to a stage and a start/end time, one row at a time or in bulk. Create, edit, reorder, duplicate and delete schedule rows that pair a competition with an event stage and a time slot. Use Bulk Create to schedule many competitions across several stages at once, then print a run sheet."},{"key":"automate-schedule","routes":["/CompetitionSchedule/AutomateSchedule","/CompetitionSchedule/RenderAutomateSchedule"],"keywords":["automate schedule","auto schedule","generate schedule","generate timetable","timeline view","stage schedule view","table view","not allowed times","time gap","minimum participants","schedule conflicts","save to schedule"],"tasks":["Auto-generate a schedule","Block a stage's break time","Manually place a competition","Add another day"],"labels":["Automated / Manual","Save Preferences","Generate Schedule","Save To Schedule","Add Section / Remove Section","Add Not Allowed Window","Export to Excel / Print A3","Force Date Lock / Manual Date Override","Date / Section / Start Time / End Time","Time Gap (mins)","Min Participants","Stage Preferences","Not Allowed Times","Section-Stage Competition Assignment"],"about":"Auto-generate a full competition timetable across stages, or drag-and-drop it manually. Builds a schedule for every competition by packing them into stages and time sections, based on stage preferences, minimum participants and blocked times. Switch to Manual mode to drag competitions onto stages instead, then export or print the result."},{"key":"live-schedule","routes":["/CompetitionSchedule/RenderLive"],"keywords":["live schedule","run sheet","event day","start competition","finish competition","move to top","reorder competitions","schedule clash","participant clash","stage column","running order","expected time"],"tasks":["Run a stage","Bring a competition forward","Fix a clash"],"labels":["Start","Finish","Move to top (double arrow)","Move up / Move down (arrows)","Drag (grip icon, computer only)","Leave blank (on a top competition that clashes)","Extra time for all (above the stages)","Done % (on the top box)","Reopen","Search and Stage","Refresh","Number badge","Time on each box (clock icon)","Participants line","Stage heading","Clash (red)","Now"],"about":"Run the event day: one column per stage, the competition at the top of each stage is the one happening now, with live clash warnings. A live run sheet for coordinators, built to work on a phone. Each stage has its own column, like the Automate Schedule timeline. Competitions are in Schedule Table order, and each box is as tall as the time the competition is expected to take. The competition at the top of a stage is the one happening now: the order decides this, not the status. Only the top competitions of the different stages are checked against each other, and a clash is shown if the same participant is in two of them."},{"key":"send-schedule","routes":["/CompetitionSchedule/RenderSend"],"keywords":["send schedule","email schedule","schedule email","tomorrow schedule","notify participants","bulk email participants","preview email","participant timing","auto send schedule","approve schedule","schedule reminder","email limit","arrive before","arrive early","view all schedule","live schedule link"],"tasks":["Send tomorrow's schedule","Send the schedule automatically","Send again to people whose email failed"],"labels":["Day (date picker)","Click a name","Checkbox on a row, or the top checkbox","Send to N","Approve this day","Search","Refresh","Emails to send","Competitions that day","People without email","Waiting / Sent / Failed badge on a row","Progress bar"],"about":"Email every participant their own schedule for one day, followed by the full schedule, with a View all schedule button. Emails are queued and sent slowly. A day can be approved for the automatic send. Use it the day before the event. Choose the day, check who will get an email, open any email to see exactly how it looks, then send. Each email lists the person's own competitions with time and stage first, then the whole day's schedule, one table per stage, and a View all schedule button to the public schedule page. The mail service allows only a limited number of emails per minute and per hour, so the emails go into a queue and are sent slowly. You can leave the page; the progress bar shows how many are sent."},{"key":"clash-matrix","routes":["/CompetitionSchedule/RenderClashes"],"keywords":["clash matrix","schedule clash","participant clash","same participant two competitions","conflict matrix","competition conflicts","print clash matrix","clash details","age group clashes"],"tasks":["Find clashes before the event"],"labels":["Age group (choose several)","Include Common competitions","Display mode","Status (choose several)","Search","Click a square","View all clashes for (in Clash Details)","All clashes list","Print","View Schedule","Download","Group heading rows have an arrow","Total competitions / Clash pairs / No clash pairs / With a clash","Red square","Green square","Dark square","Shared participants (bottom row)","Number before a name"],"about":"A grid of every competition against every other one. Red means the same participant is in both. Green means nobody is. Can be printed on a landscape sheet. Shows all participant clashes between the competitions in the Schedule Table at a glance. Competitions are grouped by age group and listed down the left side and across the top in the same order. Each square compares the competition in its row with the one in its column. Use it before the event to find competitions that should not run at the same time."},{"key":"event-stages","routes":["/EventStages/RenderManage","/EventStages/ManageNew","/EventStages/Manage"],"keywords":["stage","stages","venue","event stages","hall","auditorium","add stage","reorder stage","main stage","stage setup","stage order","location","arena"],"tasks":["Add a stage","Reorder stages","Edit or remove a stage","Update several stages at once"],"labels":["Add Event Stage","Edit","Delete","Move up / Move down","Duplicate Selected (N)","Delete Selected (N)","Show inactive stages","Search","Change title/venue/description/order to...","Title","Venue","Set Order Manually","Order","Description","Status"],"about":"Set up the physical stages/venues used to schedule competitions and run the live status board. Create and manage the list of stages (e.g. Main Stage, Hall A) for the event, each with a title, venue, description and display order. Needed before scheduling competitions or using Token System / Competition Status."},{"key":"token-system","routes":["/Coordinator/TokensystemNew","/Coordinator/RenderTokensystem","/Coordinator/tokensystem"],"keywords":["timer","token system","countdown","now performing","stage timer","competition clock","call candidates","queue","call next","time limit","warning bell","stage display","full screen timer"],"tasks":["Time a competition","Show it to the audience","Move between participants","Pause or reset the clock","End the competition"],"labels":["Start / Pause / Stop / Restart","Fullscreen / Exit fullscreen","Start Timer (on a stage card)","Candidates (on a stage card)","Previous/Next chevrons","Finish","Close (X)","Status dropdown (on a stage card)","Finished / Upcoming chips","Now Performing","Timer","Previous / Upcoming","On Going"],"about":"Run a live competition timer with a Now Performing display, for timing and calling candidates on stage. Start, pause and step through a countdown timer per competition, move through participants one by one, and show the current performer full-screen for a projector or stage screen."},{"key":"competition-draw","routes":["/Coordinator/DrawCard","/Coordinator/RenderDrawCard","/Draw/DrawCard","/Draw/RenderDrawCard"],"keywords":["draw","draw cards","draw order","performance order","lot draw","drawing lots","random order","participant order","batch draw","redraw","draw identity number","draw score card","on-stage order"],"tasks":["Draw performance order","Split into batches","Fix one participant","Reset the draw"],"labels":["Select Competition","Draw Batches","Change Status","Draw Now","Draw Batch N Only","Confirm","Reset Draw","Draw number","Active/Inactive","Move to Batch","Set Draw Identity Number"],"about":"Randomly draw performance order (and optional custom draw ID) for participants in one competition. Shuffle active participants of a competition into a random performance order, optionally in separate batches, then save it. Also lets you mark a participant inactive/absent or set a manual draw number."},{"key":"competition-status","routes":["/Coordinator/CompetitionStatusNew","/Coordinator/RenderCompetitionStatus","/Coordinator/CompetitionStatus"],"keywords":["competition status","live board","now performing","stage screen","projector","live status board","who's performing","on stage now","competition tracker","fullscreen display","on progress competitions","stage board"],"tasks":["Display it on a screen or projector","Add a missing stage"],"labels":["Fullscreen / Exit Fullscreen","On Going","Now Performing","Finished","Upcoming"],"about":"Live board showing which competition is running per stage, who is performing now, and who's next. A read-only screen for a stage or projector: an On Going ticker of live competitions, and one card per stage showing the current performer plus finished and upcoming participants. Auto-refreshes."},{"key":"result-dashboard","routes":["/Coordinator/RenderResultsStatus","/Coordinator/ResultsStatus"],"keywords":["result dashboard","competition progress","judge status","results published","competition status","judge assignments","scoring progress","not started","finished","on review","publish results"],"tasks":[],"labels":["Refresh","Search","Show only published results","Group tabs","Status tabs","Change Status (per competition)","Assign Winners","Click a competition row","Change Status (per judge)","Reset Results (per competition, Coordinator only)","Category","Age Group","Stage","Judges","Results Published","Overall Progress"],"about":"See every competition's progress, judge scoring status, and whether its result is published, in one dashboard. Shows every competition in the event with its status, its judges' scoring progress, and whether the result has been published. Use it to check what still needs judges, scoring or publishing before moving on to Assign Winners."},{"key":"reset-results","routes":["/Coordinator/RenderResetResults"],"keywords":["reset results","clear results","delete scores","remove ranks","start again","judges score again","reset competition","wrong scores"],"tasks":[],"labels":["Tick the box under each part","Delete All Results","Cancel","Judge scores","Ranks","Judge status","Competition status","What stays"],"about":"Shows everything that will be deleted or changed, then clears the results of one competition after you tick every box. Opens from the Reset Results button on a competition in the Result Dashboard (Coordinator only). It lists the judge scores, scores for each judging point, ranks, score history, judge status changes and the competition status change. Nothing is deleted until you tick a box for every part that has something to remove and press Delete All Results. The competition is then set back to Not Started and every judge back to Allowed to fill, so the judges must score again."},{"key":"split-merge-competitions","routes":["/Coordinator/RenderSplitMergeCompetitions"],"keywords":["split competition","merge competition","boys and girls","male female","separate by gender","both genders","combine competitions","split by language","merge languages","language wise competition","separate language"],"tasks":[],"labels":["Split / By gender","Split / By language","Select candidates and Move","Merge / By gender","Merge / By language","This one stays","Also put each new competition on the schedule (split)","Tick the box and press Split Competition or Merge Competitions","Candidates","Schedule","Judges","Settings that are different (merge)"],"about":"Splits a competition by gender or by language, or merges competitions back into one. Shows what happens to the candidates before it changes anything. Use this when a competition should be run separately for boys and girls, or in separate languages, or the other way round. Choose Split or Merge, then By gender or By language, pick the competition, and read the preview: which candidates stay, which move, what happens to the schedule and judges, and anything that blocks the change. Nothing changes until you tick the box and press the button."},{"key":"payments","routes":["/Coordinator/RenderPayments"],"keywords":["payments","paid","receipt","reference","pending amount","fees received","who paid"],"tasks":[],"labels":["Search","Sort a column","Participant","Date","Reference","Covers","Amount","Recorded by"],"about":"Lists every payment recorded for the event: who paid, how much, the date, the receipt or transaction reference, and which competitions it covers. Use this to check what has been received. Search by participant name, chest number or reference. The total at the top is the sum of the payments shown. Payments are recorded from a participant's Payment details, not on this page."},{"key":"assign-winners","routes":["/Coordinator/RenderResults","/Coordinator/ResultsNew","/Coordinator/Results"],"keywords":["assign winners","assign rank","generate rank","publish result","first second third","rank participant","judge scores","score details","manage results","competition status","auto generate rank","podium"],"tasks":[],"labels":["Change Status","Generate Rank 1 & 2","Generate Rank 1 - 3","Assign Rank (per participant)","Score Details","Show judges","Search competitions / category filter","Group tabs","Rank","Participant","ID Number","Score Details"],"about":"Review each competition's scores, change its status, and assign or auto-generate ranks to publish the result. Pick a competition to see every participant's total score and each judge's score. Change the competition's status, then assign First/Second/Third (or auto-generate them) to publish the result."},{"key":"assign-results-manually","routes":["/Coordinator/SportsResultManagement","/Coordinator/RenderSportsResultManagement"],"keywords":["sports result","direct rank","assign rank manually","no judges","athletics result","cancel empty competition","sports competition","rank assignment","manual result"],"tasks":["Assign a rank without judge scoring"],"labels":["Change Status","Assign Rank (per participant)","Cancel all N competitions with no participants","Move Selected to Cancelled","Group tabs","Search competitions / category filter","#","ID No","Reg. ID","Name","Assign Rank","Current Rank"],"about":"Assign ranks directly to participants for sports-style competitions that are not scored by judges. For competitions decided by results rather than judge scoring (sports events), pick a competition and assign each participant's rank directly, with no scorecard. Also change competition status and cancel competitions with no participants."},{"key":"round-management","routes":["/Coordinator/RoundManagement","/Coordinator/RenderRoundManagement"],"keywords":["rounds","heats","semi final","final round","round management","split into heats","knock out","who goes through","next round","plan rounds"],"tasks":["Run a competition in heats and a final"],"labels":["Plan rounds","Add everyone / Split evenly","Place in / Move to","Remove","Copy this plan","Assign winners","Level","People who go through","Went through, waiting for a place"],"about":"Plan rounds and heats for each competition, place people in them, and follow who goes through. A competition can run in rounds (for example Heat 1, Heat 2, Semi Final, Final). Here the coordinator plans the rounds of each competition, puts people in them, splits people evenly into heats, and sees who went through to the next round. A competition with no rounds is one final round and works as before."},{"key":"assign-round-winners","routes":["/Coordinator/RoundResults","/Coordinator/RenderRoundResults"],"keywords":["round winners","heat results","rank a heat","go through","qualify","final result","round results","semi final result"],"tasks":["Rank a heat and send the top people to the final"],"labels":["Competition","Round tabs","Rank in this round","People who go through","Result","Save winners / Save final results","Clear round results","ID No","Name","Next round"],"about":"Rank the people in one round of a competition; the top ones go through to the next round. Pick a competition that has rounds, pick a round, and give each person a rank. In a round before the final, the people ranked inside the number who go through move to the next round and appear there in Round Management. In the final round the ranks are the real results (First, Second, Third) and are saved to the normal results."},{"key":"print-judges-assignment","routes":["/Coordinator/RenderPrintJudgesAssignment"],"keywords":["judges assignment report","print judges assignment","judge list print","judge allotment print","who judges what","judges per stage"],"tasks":[],"labels":["Refresh","Print","Download","Columns","Show (Summary, Judges Overview, Detailed Assignments by Judge)","Page Break (left pane)","Color Theme (Colorful or Normal)","Letterhead toggles (Allow Organization Logo, Allow Event Logo, Allow Event Name, Allow Horizontal Line)","Stage and Filling Status filters (left)","Order Judges By","Judges list (left)","Font, Content FontSize, Padding, Column Min Width, Text Align, Allow Wrap","Additional Column Count","Stage(s)","Assigned","Filled","Pending","Filling Status"],"about":"Print one sheet showing every judge's assignments: totals, a judges overview and each judge's competitions. Shows a print-ready A4 sheet built from the Assign Judges data. It has summary tiles (judges, competitions, assignments, competitions without judges), a Judges Overview table (stages, assigned, filled, pending and a progress bar) and, for each judge, their competitions with category, stage and filling status. Print it or download it as a PDF."},{"key":"print-judges-scores","routes":["/Coordinator/PrintJudgesScoreNew","/Coordinator/RenderPrintJudgesScore","/Coordinator/PrintJudgesScore"],"keywords":["judges score","print judges score","judge scorecard","criteria score","mark published","mark finished","judge report","score breakdown","print score"],"tasks":[],"labels":["Competition","Judge","Refresh","Print","Download","Columns (Chest No., Id No., Participant Name)","Allow Score","Mark this judge's score as published","Mark as finished","Letterhead toggles (Allow Organization Logo, Allow Event Logo, Allow Event Name, Allow Horizontal Line)","Chest No.","Id No.","Participant Name","Score"],"about":"Print or download one judge's per-criteria scores for a competition, and mark that judge's score published. Pick a Competition and a Judge to preview that judge's score for every participant, broken down by criteria. Print it, download it as a PDF, or mark the judge's score published and the competition finished."},{"key":"all-results","routes":["/Coordinator/PrintResultNew","/Coordinator/RenderPrintResult","/Coordinator/PrintResult"],"keywords":["all results","print results","results sheet","download results pdf","rank grade","total points","generate ranks","publish competition","competition results print"],"tasks":[],"labels":["Competition","Filter by Competition multiple list","Refresh","Print","Download","Columns","Yes, the competition has finished! Generate ranks automatically","Letterhead toggles (Allow Organization Logo, Allow Event Logo, Allow Event Name, Allow Horizontal Line)","Rank","Total Marks / Average Marks","Total Points","Problematic Judge","Judges Score"],"about":"Print or download a full results sheet for one or more competitions, with a wide choice of columns. Pick a competition (or several, via the multiple list) to preview its results, choose which columns to show, then print or download the sheet as a PDF. Can also generate ranks and publish a competition from here."},{"key":"candidate-results","routes":["/Coordinator/CandidateWiseResults","/Coordinator/RenderCandidateWiseResults"],"keywords":["candidate results","results matrix","candidate wise results","rank letter","export pdf","first second third","results by candidate","results table"],"tasks":[],"labels":["Top Count","Font Size","Load Results","Export to PDF","Participant Name","DOB","Reg Id","Level columns (e.g. House/Class)","Competition columns"],"about":"A matrix of every candidate against every competition, showing each candidate's rank letter per competition. Shows one table per age group with a candidate on every row and a competition in every column, marking the rank (First/Second/Third) each candidate won. Use it to see each candidate's overall results at a glance and export it to PDF."},{"key":"trophy-stickers","routes":["/Coordinator/StickerBasedResults","/Coordinator/StickerBasedResults/:profileName","/Coordinator/RenderStickerBasedResults"],"keywords":["trophy sticker","winner sticker","team sticker","group sticker","print stickers","sticker design","sticker sheet","design studio","competition winners sticker"],"tasks":[],"labels":["Options","Load Candidates","Print","Download","Allow Grade Without Ranks","Cards per row / Rows per page","Card contents (%)","Card layout"],"about":"Design and print trophy stickers for each competition's team/group winners, with looks, layout options and print sheets. A design tool for printing trophy stickers for competition winners. Pick a look, load the winners, adjust the sheet layout, and print or download the sticker sheet as a PDF."},{"key":"individual-stickers","routes":["/Coordinator/StickerBasedIndividualResults","/Coordinator/StickerBasedIndividualResults/:profileName","/Coordinator/RenderStickerBasedIndividualResults"],"keywords":["individual sticker","winner sticker","print stickers","sticker design","sticker sheet","design studio","individual winner","competition winner sticker"],"tasks":[],"labels":["Options","Load Candidates","Print","Download","Cards per row / Rows per page","Card contents (%)","Card layout"],"about":"Design and print stickers for individual competition winners, with looks, layout options and print sheets. A design tool for printing stickers for individual winners. Pick a look, load the winners, adjust the sheet layout, and print or download the sticker sheet as a PDF."},{"key":"live-results","routes":["/Coordinator/RenderLiveResultPresentation"],"keywords":["live results","podium presentation","fullscreen results","winner announcement","first second third","results slideshow","announce winners","projector results"],"tasks":[],"labels":["Fullscreen","Trophy button (or Right arrow key)","Arrow button (or Left arrow key to go back)","Competition strip","Rank badge (First/Second/Third)"],"about":"A fullscreen podium presentation that reveals each competition's First, Second and Third place winners one at a time. Presents published competition results as a slideshow, revealing winners one by one with animation. Use it on a screen or projector during a results announcement ceremony."},{"key":"result-presentation","routes":["/Coordinator/RenderResultPresentation","/Coordinator/ResultPresentation"],"keywords":["result presentation","show results on projector","show score on screen","live results","announce winners","podium results","row wise results","overall championship","individual champions","award presentation","full screen","start over","reveal winners","projector"],"tasks":["Show live results on a projector","Restart a presentation"],"labels":["Announce Winner","Next Competition / Next Award","Start Over","Full Screen","Competition / Group / Award chips","Champion Order","Top Individual Count","Level","Top Count"],"about":"Live full-screen slideshow that reveals competition winners on a projector or screen, one at a time. Use this on the event day to reveal results live on a projector or big screen. Switch between five views and click Announce Winner to reveal each result one by one with a drumroll and confetti."},{"key":"publish-online","routes":["/Coordinator/PublishResultsNew","/Coordinator/RenderPublishResults","/Coordinator/PublishResults"],"keywords":["publish online","publish results","group wise results","overall championship","individual champions","export to excel","export to pdf","share results","results sheet","print results"],"tasks":["Publish results to the public event page","Share one competition's result as an image"],"labels":["Settings","Refresh","Winner Photos","Print","Publish Online","Export to Excel / Export to PDF","Share as post / Print this competition","Share (after publishing)","Top Count","Results Filter By","Overall Championship Levels","Top Champions Order","Show Team Members / Hide Id Number","Show Marquee / Marquee Content"],"about":"The main published results sheet: Overall Championship, Individual Champions and Group Wise Results together. Use this to review the full result sheet and publish it to the public event page. Shows the champion unit per level, the top individual candidates, and every competition's results by group."},{"key":"public-event-pages","routes":["/Coordinator/PublicPages"],"keywords":["public event page","public results","publish online","website for event","public link","share event online","no login results","event page for parents","public address","export event data"],"tasks":["Turn on the public event page","Publish results to the public page","Take the public page down"],"labels":["Refresh","Public Event Pages (switch)","Copy","Open","Export now","Publish results online / Publish again","View","Unpublish","Remove public documents","Result set","Champions per unit","Show podium","Show ID numbers","Show team members"],"about":"Turn on a public website page for your event, and publish results to it, without needing a coordinator login. Use this to give visitors (parents, participants) a public web address showing your event's competitions, participant counts, stages and live status, and to publish a result set they can view without logging in."},{"key":"publish-with-awards","routes":["/Coordinator/PublishResultsWithAwardsNew","/Coordinator/RenderPublishResultsWithAwards","/Coordinator/PublishResultsWithAwards"],"keywords":["publish with awards","special awards","award winners","overall championship","group wise results","export to excel","publish online","results with awards"],"tasks":["Publish results with awards","Download the awards list as Excel"],"labels":["Settings","Refresh","Winner Photos","Print","Publish Online","Export to Excel (Grouped / Single Line / Line By Line)","Export to PDF","Share as post / Print this competition","Top Count","Results Filter By","Overall Championship Levels","Font Size / Group Results Per Row","Show Team Members / Hide Id Number","Show Marquee / Marquee Content"],"about":"Published results sheet with Overall Championship, special Awards and Group Wise Results. Use this to review and publish a result set that includes the event's special awards alongside the champion unit per level and every competition's results by group."},{"key":"podium-results","routes":["/Coordinator/PublishPodiumResultsNew","/Coordinator/RenderPublishPodiumResults","/Coordinator/PublishPodiumResults"],"keywords":["podium results","medal stand","first second third","overall championship","individual champions","publish online","group wise results","results sheet","publish results"],"tasks":["Publish podium results"],"labels":["Settings","Refresh","Winner Photos","Print","Publish Online","Export to Excel (Grouped / Single Line / Line By Line)","Export to PDF","Share as post / Print this competition","Top Count","Top Champions Order","Overall Championship Levels","Font Size / Group Results Per Row","Show Team Members / Hide Id Number"],"about":"Published results sheet showing each competition's winners as a podium, plus Overall Championship and Individual Champions. Use this to review and publish results with a podium (medal-stand) display for each competition's First, Second and Third place, alongside the champion unit per level and top individuals."},{"key":"individual-results","routes":["/Coordinator/PublishIndividualResultsNew","/Coordinator/RenderPublishIndividualResults","/Coordinator/PublishIndividualResults"],"keywords":["individual results","group wise results","per competition results","publish online","export to excel","results sheet","publish results","competition results"],"tasks":["Publish just the per-competition results"],"labels":["Settings","Refresh","Winner Photos","Print","Publish Online","Export to Excel (Grouped / Single Line / Line By Line)","Export to PDF","Share as post / Print this competition","Top Count","Results Filter By","Font Size / Group Results Per Row","Show Team Members / Hide Id Number"],"about":"A simpler published results sheet with just the per-competition Group Wise Results. Use this to review and publish only the per-competition results (Group Wise Results), without the Overall Championship, Individual Champions or Awards sections shown on the other Publish Results pages."},{"key":"calculate-awards","routes":["/Coordinator/PublishAwardsResultsNew","/Coordinator/RenderPublishAwardsResults","/Coordinator/PublishAwardsResults"],"keywords":["calculate awards","special awards","award winners","category awards","publish online","award rules","results sheet","award list"],"tasks":["Check and publish award winners"],"labels":["Settings","Refresh","Winner Photos","Print","Publish Online","Export to Excel (Grouped / Line By Line)","Export to PDF","Share (after publishing)","Top Count","Champions Need Minimum Points","Hide all winners labels and status"],"about":"Shows the winner of each of the event's configured special awards, and can publish just that list online. Use this to check who wins each configured special award before or after announcing them, and to publish just the awards list to the public event page."},{"key":"social-media","routes":["/Coordinator/RenderPublishToSocialMedia","/Coordinator/RenderPublishToSocialMedia/:profileName"],"keywords":["social media","share results","instagram post","whatsapp post","result card","competition winners","individual champions","overall championship","design profile","looks","background","podium layout"],"tasks":["Create and share a post for one competition's winners","Make a separate design profile"],"labels":["Load Results / Load Champions / Load Championship","Profiles panel","Looks tab","Image tab","Options > Filters","Share / Save image","Save all","Age group / Competition item / Published competitions","Winners layout","Champions by","Level"],"about":"Create shareable image posts of competition winners, individual champions or overall championship results. Use this to design and share photo-card posts for social media - competition winners, top individual champions, or the overall championship. Pick a look and background, then share or save each post as an image."},{"key":"social-media-classic","routes":["/Coordinator/RenderPublishToSocialMediaClassic"],"keywords":["social media classic","share results","whatsapp results","instagram results","result card","download image","post together","post individually"],"tasks":["Share all winners of a competition together","Share one winner's result individually"],"labels":["Competition list","Landscape / Portrait","Template","Make all 16","Toggle Word Wrap","Share (round icon button)","Download Image","Try Again"],"about":"Older page for creating and sharing winner result-card images for social media, one competition at a time. Use this to create a photo card for a competition's winners and share or download it, e.g. for WhatsApp or Instagram. Superseded by the newer Social Media page, but still available."},{"key":"winner-photos","routes":["/Coordinator/WinnerPhotos"],"keywords":["winner photos","upload photo","candidate photo","profile picture","crop photo","result card photo","social media photo","replace photo"],"tasks":[],"labels":["Refresh","Upload (per winner)","Change (per winner)","Edit (per winner)","Remove uploaded photo (X icon)"],"about":"Upload or replace a photo for each competition winner, used on Social Media posts and published results. Use this to add or fix a candidate's or team's photo before publishing or sharing results, when the profile picture on file is missing or wrong. Uploaded photos appear on Social Media posts and published result pages."},{"key":"champion-certificate","routes":["/Coordinator/PrintTopCertificateNew","/Coordinator/RenderPrintTopCertificate","/Coordinator/PrintTopCertificate"],"keywords":["champion certificate","top certificate","overall champion","individual champion certificate","print certificate","certificate design","download certificate pdf","champions by points","certificate profile"],"tasks":["Print champion certificates"],"labels":["Load Champions","Profiles panel","Looks tab","Image tab","Style tab","Sentence / List","Body HTML","Print","Download","Champions by","Top count","Paper"],"about":"Design and print certificates for the event's overall individual champions - the same rankings as Individual Champions. Use this to print a certificate for each top individual champion (by total points, or split by gender or age group), using the same champion rankings shown on Publish Results and the Social Media Individual Champions post."},{"key":"rank-certificates","routes":["/Coordinator/PrintCertificateNew","/Coordinator/RenderPrintCertificate","/Coordinator/PrintCertificate"],"keywords":["rank certificate","first second third certificate","grade certificate","print certificate","winner certificate","certificate design","download certificate pdf","ranked winners","competition certificate"],"tasks":["Print rank certificates for a competition"],"labels":["Load Candidates","Profiles panel","Looks tab","Image tab","Style tab","Sentence / List","Body HTML","Print","Download","Age group / Competition item","Published competitions","Include grade","Paper"],"about":"Design and print certificates for ranked (First/Second/Third) or graded winners of chosen competitions. Use this to print a certificate for each ranked candidate or team in the competitions you choose, or also grade-only winners if you include grades. One certificate per winner, not an overall championship."},{"key":"participation-certificates","routes":["/Coordinator/PrintParticipantCertificateNew","/Coordinator/RenderPrintParticipantCertificate","/Coordinator/PrintParticipantCertificate"],"keywords":["participation certificate","certificate of participation","print certificate for all candidates","certificate design","download certificate pdf","enrolled candidates certificate","certificate for all participants","group certificate"],"tasks":["Print participation certificates for a group"],"labels":["Load Candidates","Profiles panel","Looks tab","Image tab","Style tab","Sentence / List","Body HTML","Print","Download","Group","Unit (e.g. House/District)","Participant type","Filter by ID numbers"],"about":"Design and print participation certificates for every candidate or team enrolled in a group, listing their competitions. Use this to print a certificate for every enrolled candidate or team in a chosen group, listing the competitions they took part in - not limited to winners or ranked results."},{"key":"quiz","routes":["/Quiz/RenderManage","/Quiz/PrepareQuestions"],"keywords":["quiz","quiz competition","create quiz","quiz settings","kahoot","quiz master","join pin","start quiz","quiz language","live quiz control"],"tasks":["Create a quiz","Start a quiz live","Delete a quiz"],"labels":["+ New","Create Quiz / Save Changes","Prepare questions","Start","Presentation","Close","Delete","Reveal / Close (question)","Start / Close (round)","Run AI review","Competition","Title","Description","Default seconds / question","Enforce fullscreen & track fouls","Ask candidates to share their camera","Quiz language","Accept transliterated answers","Ask for date of birth on join"],"about":"Create and manage quiz competitions, then hand off to write questions or run them live. Create a quiz linked to a competition, set its rules (timing, fullscreen, language, DOB check) and manage it. Once live, run and monitor it here, or from the Presentation screen."},{"key":"quiz-prepare","routes":["/Quiz/PrepareQuestions/:quizId"],"keywords":["quiz questions","add question","quiz options","answer key","generate questions with ai","rounds","multiple choice","free text question","quiz master","math question"],"tasks":["Add a question","Generate questions with AI","Split questions into rounds"],"labels":["Generate questions with AI","Generate / Regenerate","Select all","Add selected","+ Add Question","+ Add round","Edit / Delete (question)","Delete selected","Refresh questions","Question","Multiple choice / Free text","Render as math","Time (s)","Points","Lang","Options / Accepted answers"],"about":"Write and manage one quiz's questions, options, answer keys and rounds, or generate them with AI. Add, edit and delete a quiz's questions (multiple choice or free text), group them into rounds, and use AI to generate question drafts you can review and add. This is the only quiz screen a quiz master can open."},{"key":"quiz-present","routes":["/Quiz/Present/:quizId"],"keywords":["present quiz","run quiz live","quiz pin","start quiz","join pin","quiz lobby","venue location","quiz screen","show options","full screen quiz"],"tasks":["Run a quiz live"],"labels":["Fullscreen","Start quiz","Close quiz","Exit","Next — show first/next question","Show options","Pin venue here / Re-pin venue here","Game PIN","Candidates join at"],"about":"Full-screen display to run a live quiz: show the join PIN, reveal questions, and manage the venue. The big-screen view coordinators use to run a quiz live. Start it to mint a join PIN, watch who has joined and is nearby, then reveal each question with Next. Quiz masters cannot open this screen."},{"key":"assign-quiz-masters","routes":["/Quiz/AssignQuizMasters"],"keywords":["assign quiz masters","allot quiz master","quiz master competitions","by judge","by competition","bulk assign","select all","invite quiz master","quiz master allotment"],"tasks":["Assign a quiz master to a competition","Assign several competitions at once"],"labels":["Invite Judges","(tick a box)","Select","Assign (N)","Update status","Edit","Delete","Score status"],"about":"Allot quiz masters to competitions so each can prepare that competition's quiz questions. Assign quiz masters to the competitions they will write questions for. Work from a quiz master (tick their competitions) or from a competition (tick its quiz masters), one at a time or in bulk."},{"key":"manage-account","routes":["/Profile/ProfileSettingsNew","/Profile/RenderProfileSettings","/Profile/ProfileSettings"],"keywords":["profile","account settings","change password","update name","phone number","mobile number","date of birth","sign out","log out","switch event"],"tasks":["Update your profile","Change your password","Switch to another event","Sign out"],"labels":["Save Changes","Change your password","Name","Email","Phone","Mobile","Date of Birth","New Password"],"about":"Update your name, phone, mobile number and date of birth, and change your password. Edit your personal profile details and set a new password, all from one form. Your email is shown but can't be changed here."},{"key":"my-roles","routes":["/MyRoles/RenderIndex","/MyRoles/Index","/MyRoles/IndexNew","/MyRoles/IndexOld"],"keywords":["my roles","switch event","switch role","change event","use this role","remove role","multiple events","coordinator of another event","recent roles"],"tasks":["Switch to another event","Remove a role you no longer need"],"labels":["Go to Dashboard","Use this role","Remove my role","Role @ Event"],"about":"See every role and event you have, switch to another one, or remove a role you added yourself. Lists your currently active role and event, plus every other role you hold — for example, coordinator of a different event. Switch to any of them, or, on a User account, remove one you no longer need."},{"key":"billing","routes":["/Billing/RenderIndex","/Billing/Index"],"keywords":["billing","bill","invoice","pay","payment","bank transfer","i am paid","request billing","event price","how much does it cost"],"tasks":["Get a bill for an event","Pay a bill"],"labels":["Request billing","Download invoice","I am paid","Host country","Type of organization","Event level","Support mode"],"about":"Ask for billing on your events, see the bill, pay by bank transfer, then tell us you paid. Billing is set per event. For each event you created, you can ask for billing. We check the event and email you the bill with the bank details. You pay by bank transfer, then click I am paid. You cannot set the price yourself."},{"key":"activity-logs","routes":["/Coordinator/ActivityLogNew","/Coordinator/RenderActivityLog","/Coordinator/ActivityLog"],"keywords":["activity log","audit log","who did this","history","event log","search log","changes log","action log"],"tasks":["Find what happened to something"],"labels":["Refresh","Log / Created (column headers)","Search box","Log","By","Created"],"about":"A searchable, sortable list of actions recorded for this event, with who did it and when. Shows a running log of activity on the event, so you can check what happened, when and by whom. Search across every column and sort by log text or date."},{"key":"bug-reports","routes":["/BugReports"],"keywords":["bug report","report a bug","report a problem","issue tracker","screenshot bug","bug status","technical issue","app problem"],"tasks":["Report a bug","Change a bug's status"],"labels":["(screenshot thumbnail)","Status dropdown","Screenshot","Description","Status","Event Id","Created By","Created Date"],"about":"See bugs you reported — or, for admins, every bug reported for the event — and their status. Lists bug reports with a screenshot, description, status, event, reporter and date. A few admin roles can also change a bug's status here. New bugs are reported from a button available on every page."},{"key":"stage-manager","routes":["/StageManager/Index","/StageManager/RenderIndex"],"keywords":["stage manager","my stage","stage","competition status","start competition","finish competition","stage participants","stage schedule","now performing","current participant","highlight"],"tasks":["Start a competition","Mark the participant who is performing"],"labels":["Upcoming, On Progress, Finished tiles","Tap a participant number","Start / Finish (top right of the competition panel)"],"about":"The Stage Manager's page: the competitions on your stage, who performs in them, and their status. Stage Managers look after one stage. This page lists every competition scheduled on that stage in time order. You start and finish each competition with one button, see the participants by number, and tap a number to highlight the current participant. You only see your own stage."},{"key":"forgot-password","routes":["/ForgotPasswordPage"],"keywords":["forgot password","forgot my password","reset password","password reset","cannot login","cant login","unable to login","login problem","lost password","change password without login","otp for password","password marannu","password maranno","login cheyyan pattunilla"],"tasks":["Reset a forgotten password"],"labels":["Get OTP via Email","Change Password","Email","OTP","New Password and Confirm Password"],"about":"Reset a forgotten password with a one-time code sent to your email. No login needed. The page for anyone who cannot log in because they forgot their password. You confirm your email with a 6-digit OTP, choose a new password, and are logged in with it."},{"key":"competition-rules","routes":["/SetUp/RenderCompetitionContents"],"keywords":["competition rules","competition description","rules for each competition","rules template","allowed not allowed","competition video","rules pdf","hide competition from public page","competition content"],"tasks":["Write rules that apply to all competitions","Write rules for only one age group, or only for team entries"],"labels":["Add Rules","Search, and filters for competition, age group and participant type","The list is grouped by competition","Edit","Edit judging criteria","Competition","Age Group","Participant Type","Show on Public Page, Tags, Video Link, Picture","Rules","Document Title, Document Link","Tags"],"about":"Write rules for all competitions, or only for one competition, one age group, or individual or team entries - with ready-made sections (about, time and format, rules, allowed, not allowed, judging, notes) and a rules document. The public Registration Page shows each competition the rules that fit it. Works like the grades in Scoring Setup: every row of rules has a scope - competition, age group and participant type - and a choice left on All means everyone. A row with all three on All applies to every competition. Parents and participants read the rules on the public Registration Page: on each competition's own page (the rules that fit it, wide ones first, each with who it is for) and in the Rules & Criteria tab (a card for all competitions, then each competition). A row for one whole competition can also carry its tags, picture and video, and hide it from the public page. Judging criteria are not edited here - they come from Scoring Setup."},{"key":"registration-page","routes":["/Coordinator/RegistrationPage"],"keywords":["registration page","public registration page","event website","event landing page","online registration page","share registration link","publish registration page","event page for parents"],"tasks":["Put the registration page online","Hide a tab or a part of the page","Show a change in competitions or the schedule"],"labels":["Steps (Page Settings, Overview, Competitions, Schedule, Rules & Criteria, News & Updates, Venue, Gallery, FAQ)","Drag a component from the palette onto the canvas to put it on the page; select a component to change its settings; Delete in the settings removes it.","Position on the page (Overview components)","Save","Reset to Defaults","Remove All","Publish / Publish Again","Update Event Data","Copy Link / Open","Take Offline","Page Settings is a canvas like the other steps. Page Header","Page Settings - Registration","Page Settings - Tips Beside the Form","Page Settings - Contact Details","Page Settings - Footer Text","Venue component","Photo Gallery component","Rules & Criteria component","Content components on every tab"],"about":"Build and publish the event's public registration page by dragging components onto each tab - overview, competitions, schedule, rules, news, venue, gallery and FAQ - next to the online registration form. A public website page for the event at /Public/Registration/{event-name}. It is built the way the Public Registration form is: every tab is a step with its own drag-and-drop canvas, a component is on the page when it is on the canvas, and its settings are in the properties panel. A tab with nothing on it is not on the page. Competitions, age groups, fees, time limits, judging criteria and the schedule come from the event itself; the registration form is the event's Public Registration form."}]`);export{e as default};
